import CryptoKit
import Foundation
import TerminalCorpus
import TestSupport
import Testing

/// The corpus is only worth its known-miss lists while it is the proof of concept's corpus, so its
/// shape and its generated bytes are pinned.
///
/// Building and hashing the five workloads, a megabyte each, runs on a thread the tests own: see
/// `onHandoverThread`.
@Suite(.serialized, .fastPassBounded)
struct HandoverCorpusPinTests {
    /// SHA-256 of each workload up to its last cut point, taken from the proof of concept's
    /// generated workload files. A generator that drifts by one byte changes its digest.
    static let workloadDigests: [String: String] = [
        "colors": "1f0d5edff5179616b680325143c6f5a7b8253f14e571cbb8ace397fb1d85656d",
        "cursor": "62f9a1d936fd7974614a366ed3bd95e97fe072d0eaa25229b0ef275c8075bb80",
        "scroll": "643f5ad43d1f5e6c27264e752e09b894939138e943b7e2a0bdf5e3a9f6fd680b",
        "tui": "e97e06537238854bfe178231f38c609156d9a814ed618ae789831767aac89a8e",
        "unicode": "c4165d95be468ac75bf51141836afdd0c82aa506904810dd0f677506165fb4bf",
    ]

    @Test func corpusHasEveryGeneratedState() {
        let names = HandoverCorpus.names
        #expect(HandoverCorpus.scenarios.count == 81)
        #expect(names.count == 111)
        #expect(Set(names).count == names.count, "two corpus states share a name")
    }

    @Test func workloadsMatchTheProofOfConcept() async throws {
        try await onHandoverThread {
            for entry in HandoverCorpus.checkpoints {
                guard let end = entry.offsets.last else {
                    Issue.record("\(entry.workload) has no cut points")
                    continue
                }
                let bytes = HandoverCorpus.workloadBytes(entry.workload)
                #expect(bytes.count >= end, "\(entry.workload) is \(bytes.count) bytes, shorter than its last cut at \(end)")
                let digest = SHA256.hash(data: Data(bytes.prefix(end)))
                let hex = digest.map { String(format: "%02x", $0) }.joined()
                #expect(hex == Self.workloadDigests[entry.workload], "\(entry.workload) no longer generates the proof of concept's bytes")
            }
        }
    }
}
